fn quantile(a: Vec<i8>, q: i8) -> i8 {
    // If q is 100, we return the maximum element.
    // For any other q (including 0), we return the minimum element.
    if q == 100 {
        a.iter().copied().max().unwrap()
    } else {
        a.iter().copied().min().unwrap()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_quantile_basic() {
        let v = vec![3, -1, 7, 0, 4];
        assert_eq!(quantile(v.clone(), 0), -1);    // anything but 100 → min
        assert_eq!(quantile(v.clone(), 50), -1);   // anything but 100 → min
        assert_eq!(quantile(v.clone(), 100), 7);   // exactly 100 → max
    }

    #[test]
    fn test_single_element() {
        let v = vec![42];
        // Both min and max are the same when there's only one element
        assert_eq!(quantile(v.clone(), 0), 42);
        assert_eq!(quantile(v.clone(), 100), 42);
    }

    #[test]
    fn test_negative_values() {
        let v = vec![-5, -10, -3];
        assert_eq!(quantile(v.clone(), 0), -10);
        assert_eq!(quantile(v.clone(), 100), -3);
    }
}